import pytest

from cfnlint.context import create_context_for_template
from cfnlint.jsonschema import CfnTemplateValidator
from cfnlint.rules.functions.GetAtt import GetAtt
from cfnlint.template import Template


@pytest.fixture(scope="module")
def rule():
    return GetAtt()


def build_template():
    return Template(
        "",
        {
            "Resources": {
                "SimpleLambda": {
                    "Type": "AWS::ServiceCatalog::CloudFormationProvisionedProduct",
                    "Properties": {
                        "ProductName": "Basic Lambda",
                        "ProvisioningArtifactName": "1.0",
                    },
                },
                "SimpleApiGateway": {
                    "Type": "AWS::ServiceCatalog::CloudFormationProvisionedProduct",
                    "Properties": {
                        "ProductName": "API Gateway",
                        "ProvisioningArtifactName": "1.0",
                        "ProvisioningParameters": [
                            {"Key": "LambdaArn", "Value": {"Fn::GetAtt": ["SimpleLambda", "Outputs.SCLambdaArn"]}},
                        ],
                    },
                },
            }
        },
        regions=["us-east-1"],
    )


def test_getatt_dynamic_outputs_allowed(rule):
    cfn = build_template()
    context = create_context_for_template(cfn)
    validator = CfnTemplateValidator({}, context=context, cfn=cfn)

    # Directly validate the GetAtt on dynamic Outputs
    instance = {"Fn::GetAtt": ["SimpleLambda", "Outputs.SCLambdaArn"]}
    schema = {"type": "string"}

    errs = list(rule.fn_getatt(validator, schema, instance, {}))
    assert errs == [], f"Expected no E1010 errors, got {errs!r}"

